function registarUso<This, Args extends unknown[], Return>(
  alvo: (this: This, ...args: Args) => Return,
  contexto: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
) {
  console.log("FASE 1 (definicao da classe): a envolver " + String(contexto.name));
  return function (this: This, ...args: Args): Return {
    console.log("FASE 2 (chamada do metodo): " + String(contexto.name) + " foi chamado");
    return alvo.apply(this, args);
  };
}

class Notificador {
  @registarUso
  enviar(mensagem: string) {
    console.log("a enviar: " + mensagem);
  }
}

console.log("--- classe definida, ainda sem instancia ---");
const notificador = new Notificador();
console.log("--- instancia criada, ainda sem chamada ---");
notificador.enviar("ola");
// FASE 1 (definicao da classe): a envolver enviar
// --- classe definida, ainda sem instancia ---
// --- instancia criada, ainda sem chamada ---
// FASE 2 (chamada do metodo): enviar foi chamado
// a enviar: ola

function medirTempo<This, Args extends unknown[], Return>(
  alvo: (this: This, ...args: Args) => Return,
  contexto: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
) {
  const nome = String(contexto.name);
  return function (this: This, ...args: Args): Return {
    const inicio = performance.now();
    const resultado = alvo.apply(this, args);
    const duracao = performance.now() - inicio;
    console.log(nome + " demorou " + duracao.toFixed(2) + "ms");
    return resultado;
  };
}

class Relatorio {
  @medirTempo
  gerar(linhas: number) {
    let total = 0;
    for (let i = 0; i < linhas; i++) {
      total += i;
    }
    return total;
  }
}

const relatorio = new Relatorio();
console.log("total=" + relatorio.gerar(1000));
// gerar demorou <alguns ms, o valor exato varia a cada execucao>
// total=499500

function registar<T extends new (...args: any[]) => object>(alvo: T, contexto: ClassDecoratorContext) {
  console.log("decorator de classe avaliado, kind=" + contexto.kind + " name=" + String(contexto.name));
  contexto.addInitializer(function () {
    // "this" aqui e a propria classe, nao uma instancia: e um decorator de classe.
    console.log("addInitializer a correr, this=" + (this as { name: string }).name);
  });
  return class ServicoRegistado extends alvo {
    descricao = "instancia registada";
  };
}

@registar
class Servico {
  constructor() {
    console.log("construtor de Servico a correr");
  }
}

console.log("--- a criar a primeira instancia ---");
const s1 = new Servico() as Servico & { descricao: string };
console.log("--- a criar a segunda instancia ---");
const s2 = new Servico() as Servico & { descricao: string };
console.log("nome da classe efetiva=" + s1.constructor.name + ", descricao=" + s2.descricao);
// decorator de classe avaliado, kind=class name=Servico
// addInitializer a correr, this=ServicoRegistado
// --- a criar a primeira instancia ---
// construtor de Servico a correr
// --- a criar a segunda instancia ---
// construtor de Servico a correr
// nome da classe efetiva=ServicoRegistado, descricao=instancia registada

function naoNegativo(valor: undefined, contexto: ClassFieldDecoratorContext) {
  return function (this: unknown, valorInicial: number): number {
    if (valorInicial < 0) {
      throw new Error(String(contexto.name) + " nao pode ser negativo");
    }
    return valorInicial;
  };
}

class Produto {
  @naoNegativo
  preco = 10;
}

const produto = new Produto();
console.log("preco=" + produto.preco);
// preco=10

class ProdutoInvalido {
  @naoNegativo
  preco = -5;
}

try {
  new ProdutoInvalido();
} catch (erro) {
  console.log("falhou como esperado: " + (erro as Error).message);
}
// falhou como esperado: preco nao pode ser negativo

function logAcesso(alvo: ClassAccessorDecoratorTarget<unknown, number>, contexto: ClassAccessorDecoratorContext) {
  console.log("kind=" + contexto.kind + " name=" + String(contexto.name));
  return {
    get(this: unknown) {
      console.log("GET a correr");
      return alvo.get.call(this);
    },
    set(this: unknown, novoValor: number) {
      console.log("SET a correr com " + novoValor);
      alvo.set.call(this, novoValor);
    },
  };
}

class Termometro {
  @logAcesso
  accessor temperatura = 20;
}

const termometro = new Termometro();
console.log("valor=" + termometro.temperatura);
termometro.temperatura = 25;
console.log("valor=" + termometro.temperatura);
// kind=accessor name=temperatura
// GET a correr
// valor=20
// SET a correr com 25
// GET a correr
// valor=25

