function registarChamada<This, Args extends unknown[], Return>(
  alvo: (this: This, ...args: Args) => Return,
  contexto: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
) {
  console.log("[1] registarChamada avaliado sobre " + String(contexto.name));
  return function (this: This, ...args: Args): Return {
    console.log("[5] registarChamada: a chamar " + String(contexto.name) + " com " + JSON.stringify(args));
    return alvo.apply(this, args);
  };
}

class Repositorio {
  @medirTempo
  @registarChamada
  buscar(id: number) {
    console.log("[a] buscar a correr, id=" + id);
    return { id, nome: "registo " + id };
  }
}

console.log("--- classe definida ---");
const repo = new Repositorio();
console.log("[3] a chamar buscar");
const registo = repo.buscar(7);
console.log("[7] resultado=" + JSON.stringify(registo));
