function maiusculas(valor: undefined, contexto: ClassFieldDecoratorContext) {
  return function (this: unknown, valorInicial: string): string {
    return valorInicial.toUpperCase();
  };
}

class Produto {
  @maiusculas
  categoria = "eletronica";
}

const produto = new Produto();
console.log(produto.categoria);
// ELETRONICA

let totalCriados = 0;

function atribuirId(valor: undefined, contexto: ClassFieldDecoratorContext) {
  return function (this: unknown): number {
    totalCriados++;
    return totalCriados;
  };
}

class Bilhete {
  @atribuirId
  id = 0;
}

const b1 = new Bilhete();
const b2 = new Bilhete();
const b3 = new Bilhete();
console.log(b1.id, b2.id, b3.id, totalCriados);
// 1 2 3 3

function memorizar<This, Args extends unknown[], Return>(
  alvo: (this: This, ...args: Args) => Return,
  contexto: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
) {
  const cache = new Map<string, Return>();
  return function (this: This, ...args: Args): Return {
    const chave = JSON.stringify(args);
    if (cache.has(chave)) {
      console.log(String(contexto.name) + ": veio da cache para " + chave);
      return cache.get(chave) as Return;
    }
    const resultado = alvo.apply(this, args);
    cache.set(chave, resultado);
    return resultado;
  };
}

class Matematica {
  chamadas = 0;

  @memorizar
  quadrado(n: number) {
    this.chamadas++;
    return n * n;
  }
}

const matematica = new Matematica();
console.log(matematica.quadrado(4));
console.log(matematica.quadrado(4));
console.log(matematica.quadrado(5));
console.log("chamadas reais=" + matematica.chamadas);
// 16
// quadrado: veio da cache para [4]
// 16
// 25
// chamadas reais=2
